INSERT OR IGNORE INTO todos (id, title, description, status) VALUES ('build-modal-dialog', 'Build modal dialog page', 'Create a standalone HTML document for an image preview page with a closed-by-default delete confirmation modal and a trigger button with class trigger.', 'in_progress');

