const fs = require('fs');
const { chromium } = require('playwright');
(async () => {
  const html = fs.readFileSync('index.html', 'utf8');
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  await page.setContent(html, { waitUntil: 'load' });

  const initial = {
    dialogOpen: await page.locator('#confirm-delete').evaluate(el => el.hasAttribute('open')),
    triggerClass: await page.locator('#delete-trigger').getAttribute('class'),
  };

  await page.locator('#delete-trigger').click();
  const afterOpen = {
    dialogOpen: await page.locator('#confirm-delete').evaluate(el => el.hasAttribute('open')),
    activeRole: await page.evaluate(() => document.activeElement?.tagName),
    activeText: await page.evaluate(() => document.activeElement?.textContent?.trim()),
    dialogName: await page.locator('#confirm-delete').evaluate(el => el.getAttribute('aria-labelledby')),
  };

  await page.keyboard.press('Escape');
  const afterEscape = {
    dialogOpen: await page.locator('#confirm-delete').evaluate(el => el.hasAttribute('open')),
    focusedText: await page.evaluate(() => document.activeElement?.textContent?.trim()),
  };

  await browser.close();
  console.log(JSON.stringify({ initial, afterOpen, afterEscape }, null, 2));
})().catch(err => { console.error(err); process.exit(1); });
