      pointer-events: none;
      background:
        linear-gradient(rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0.02)),
        repeating-linear-gradient(
          90deg,
          transparent 0,
          transparent 23px,
          rgba(255, 255, 255, 0.02) 24px
        );
      mask: linear-gradient(180deg, rgba(0, 0, 0, 0.65), transparent 92%);
    }

