      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px 20px;
    }

    .preview-card {
      width: min(100%, 900px);
      border: 1px solid var(--border);
      border-radius: 32px;
      background: linear-gradient(180deg, rgba(19, 25, 38, 0.96), rgba(12, 16, 25, 0.96));
      box-shadow: var(--shadow);
      overflow: clip;
    }

    .preview-copy {
      padding: 28px 28px 18px;
    }

    h1 {
      margin: 0 0 10px;
      font-size: clamp(2rem, 4vw, 3.2rem);
      line-height: 1.05;
      letter-spacing: -0.04em;
    }

    h1:focus-visible {
      outline: 3px solid rgba(167, 139, 250, 0.95);
      outline-offset: 6px;
      border-radius: 10px;
    }

    .lede {
      margin: 0;
      max-width: 62ch;
      color: var(--muted);
    }

    .media {
      display: grid;
      gap: 18px;
      padding: 0 28px 28px;
    }

    .image-frame {
      border-radius: 28px;
      padding: 14px;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.02)),
        var(--panel-strong);
      border: 1px solid rgba(255, 255, 255, 0.08);
    }

    .image-frame img {
      display: block;
      width: 100%;
      height: auto;
      border-radius: 18px;
      aspect-ratio: 16 / 10;
      object-fit: cover;
    }

    .actions {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 16px;
      flex-wrap: wrap;
