      outline: 3px solid rgba(167, 139, 250, 0.95);
      outline-offset: 3px;
    }

    .trigger {
      background: linear-gradient(180deg, rgba(251, 113, 133, 0.22), rgba(244, 63, 94, 0.15));
      box-shadow: inset 0 0 0 1px rgba(251, 113, 133, 0.28);
    }

    .trigger:hover {
      background: linear-gradient(180deg, rgba(251, 113, 133, 0.3), rgba(244, 63, 94, 0.22));
    }

    dialog {
      width: min(92vw, 520px);
      border: 1px solid rgba(255, 255, 255, 0.12);
      border-radius: 28px;
      padding: 0;
      background: linear-gradient(180deg, rgba(20, 26, 40, 0.98), rgba(13, 18, 29, 0.98));
      color: var(--text);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(2, 6, 23, 0.72);
      backdrop-filter: blur(10px);
    }

    .dialog-body {
      padding: 26px;
    }

    .dialog-kicker {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      color: #fecdd3;
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      margin-bottom: 14px;
    }

    .dialog-kicker::before {
      content: "";
      width: 10px;
      height: 10px;
      border-radius: 999px;
      background: linear-gradient(180deg, var(--danger), var(--danger-strong));
      box-shadow: 0 0 0 6px rgba(251, 113, 133, 0.16);
    }

    .dialog-title {
      margin: 0;
      font-size: 1.45rem;
      line-height: 1.15;
