        );
      mask: linear-gradient(180deg, rgba(0, 0, 0, 0.65), transparent 92%);
    }

    .shell {
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px 20px;
    }

    .preview-card {
      width: min(100%, 900px);
      border: 1px solid var(--border);
      border-radius: 32px;
      background: linear-gradient(180deg, rgba(19, 25, 38, 0.96), rgba(12, 16, 25, 0.96));
      box-shadow: var(--shadow);
      overflow: clip;
    }

    .preview-copy {
      padding: 28px 28px 18px;
    }

    h1 {
      margin: 0 0 10px;
      font-size: clamp(2rem, 4vw, 3.2rem);
      line-height: 1.05;
