    }

    h1:focus-visible {
      outline: 3px solid rgba(167, 139, 250, 0.95);
      outline-offset: 6px;
      border-radius: 10px;
    }

    .lede {
      margin: 0;
      max-width: 62ch;
      color: var(--muted);
    }

    .media {
      display: grid;
      gap: 18px;
      padding: 0 28px 28px;
    }

    .image-frame {
      border-radius: 28px;
      padding: 14px;
      background:
        linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.02)),
        var(--panel-strong);
      border: 1px solid rgba(255, 255, 255, 0.08);
    }

    .image-frame img {
      display: block;
      width: 100%;
      height: auto;
      border-radius: 18px;
      aspect-ratio: 16 / 10;
      object-fit: cover;
    }

    .actions {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 16px;
      flex-wrap: wrap;
    }

    .meta {
      color: var(--muted);
      margin: 0;
    }

    button {
      appearance: none;
      border: 0;
      border-radius: 999px;
      font: inherit;
      font-weight: 600;
      padding: 0.9rem 1.15rem;
      color: var(--text);
      background: rgba(255, 255, 255, 0.08);
      cursor: pointer;
      transition: transform 160ms ease, background-color 160ms ease, box-shadow 160ms ease;
    }

    button:hover {
      background: rgba(255, 255, 255, 0.12);
    }

    button:active {
      transform: translateY(1px);
    }

    button:focus-visible,
    dialog button:focus-visible {
      outline: 3px solid rgba(167, 139, 250, 0.95);
      outline-offset: 3px;
    }

    .trigger {
      background: linear-gradient(180deg, rgba(251, 113, 133, 0.22), rgba(244, 63, 94, 0.15));
      box-shadow: inset 0 0 0 1px rgba(251, 113, 133, 0.28);
    }

    .trigger:hover {
      background: linear-gradient(180deg, rgba(251, 113, 133, 0.3), rgba(244, 63, 94, 0.22));
    }

    dialog {
      width: min(92vw, 520px);
      border: 1px solid rgba(255, 255, 255, 0.12);
      border-radius: 28px;
      padding: 0;
      background: linear-gradient(180deg, rgba(20, 26, 40, 0.98), rgba(13, 18, 29, 0.98));
      color: var(--text);
      box-shadow: var(--shadow);
    }

    dialog::backdrop {
      background: rgba(2, 6, 23, 0.72);
      backdrop-filter: blur(10px);
    }

    .dialog-body {
      padding: 26px;
    }

    .dialog-kicker {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      color: #fecdd3;
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
      margin-bottom: 14px;
    }

    .dialog-kicker::before {
      content: "";
      width: 10px;
      height: 10px;
      border-radius: 999px;
      background: linear-gradient(180deg, var(--danger), var(--danger-strong));
      box-shadow: 0 0 0 6px rgba(251, 113, 133, 0.16);
    }

    .dialog-title {
      margin: 0;
      font-size: 1.45rem;
      line-height: 1.15;
      letter-spacing: -0.03em;
    }

    .dialog-copy {
      margin: 12px 0 0;
