    .danger:hover {
      background: linear-gradient(180deg, rgba(251, 113, 133, 0.36), rgba(244, 63, 94, 0.24));
    }

    .status {
      min-height: 1.5rem;
      color: #c7d2fe;
      font-size: 0.95rem;
      margin-top: 10px;
    }

    @media (max-width: 640px) {
      .preview-copy,
      .media {
        padding-left: 18px;
        padding-right: 18px;
      }

      .preview-copy {
        padding-top: 20px;
      }

      .dialog-body {
        padding: 20px;
      }

      .dialog-actions {
        justify-content: stretch;
      }

      .dialog-actions button {
        flex: 1 1 0;
      }
    }

    @media (forced-colors: active) {
      * {
        forced-color-adjust: auto;
      }

      .preview-card,
      dialog {
        border: 1px solid CanvasText;
      }

      button {
        border: 1px solid ButtonText;
      }

      button:focus-visible,
      dialog button:focus-visible {
        outline-color: Highlight;
      }
    }
  </style>
</head>
<body>
  <main id="app"></main>

  <script>
    const h = (tag, attrs = {}, ...children) => ({ tag, attrs, children });

    function render(node) {
      if (node == null || node === false) return document.createTextNode('');
      if (typeof node === 'string' || typeof node === 'number') {
        return document.createTextNode(String(node));
      }
      if (Array.isArray(node)) {
        const frag = document.createDocumentFragment();
        node.forEach((child) => frag.appendChild(render(child)));
        return frag;
      }

      const el = document.createElement(node.tag);
      Object.entries(node.attrs || {}).forEach(([key, value]) => {
        if (key === 'className') {
          el.className = value;
          return;
        }
        if (key === 'text') {
          el.textContent = value;
          return;
        }
        if (key.startsWith('on') && typeof value === 'function') {
          el.addEventListener(key.slice(2).toLowerCase(), value);
          return;
        }
        if (value === false || value == null) return;
        if (value === true) {
          el.setAttribute(key, '');
          return;
        }
        el.setAttribute(key, value);
      });
      node.children.flat().forEach((child) => el.appendChild(render(child)));
      return el;
    }

    function ImagePreviewPage() {
      const status = h('p', {
        className: 'status',
        id: 'delete-status',
        'aria-live': 'polite'
      }, '');

      const dialog = h('dialog', {
        id: 'confirm-delete',
        'aria-labelledby': 'confirm-title',
        'aria-describedby': 'confirm-copy'
      },
        h('div', { className: 'dialog-body' },
          h('div', { className: 'dialog-kicker' }, 'Delete image'),
          h('h2', { className: 'dialog-title', id: 'confirm-title' }, 'Delete this image from your library?'),
          h('p', { className: 'dialog-copy', id: 'confirm-copy' }, 'This will permanently remove the image from your library. You can\u2019t undo this action.'),
          h('div', { className: 'dialog-actions' },
            h('button', {
              type: 'button',
              className: 'secondary',
              'data-close': 'cancel',
              autofocus: true
            }, 'Cancel'),
            h('button', {
              type: 'button',
              className: 'danger',
              'data-close': 'delete'
            }, 'Delete image')
          )
        )
      );

      const page = h('section', { className: 'shell' },
        h('article', { className: 'preview-card', 'aria-labelledby': 'page-title' },
          h('div', { className: 'preview-copy' },
            h('h1', { id: 'page-title' }, 'Image preview'),
            h('p', { className: 'lede' }, 'Review your image before deleting it from the library. The confirmation dialog stays closed until you choose Delete.')
          ),
          h('div', { className: 'media' },
            h('div', { className: 'image-frame' },
              h('img', {
                src: 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?auto=format&fit=crop&w=1600&q=80',
                alt: 'A mountain lake reflecting a dramatic blue sky at sunset'
              })
            ),
          h('div', { className: 'actions' },
            h('p', { className: 'meta' }, 'Sunset over the alpine lake · 4.8 MB'),
            h('button', {
              type: 'button',
              className: 'trigger',
              id: 'delete-trigger',
              'aria-haspopup': 'dialog',
              'aria-controls': 'confirm-delete'
            }, 'Delete image')
          ),
          )
        ),
        status,
        dialog
      );

      return page;
    }

    const app = document.getElementById('app');
    app.appendChild(render(ImagePreviewPage()));

    const trigger = document.getElementById('delete-trigger');
    const dialog = document.getElementById('confirm-delete');
    const status = document.getElementById('delete-status');
    const card = document.querySelector('.preview-card');

    trigger.addEventListener('click', () => {
      dialog.showModal();
    });

    dialog.addEventListener('click', (event) => {
      if (event.target === dialog) {
        dialog.close('cancel');
      }
    });

    dialog.addEventListener('close', () => {
      if (dialog.returnValue === 'delete') {
        card.dataset.deleted = 'true';
        card.innerHTML = '<div class="preview-copy"><h1 id="page-title" tabindex="-1">Image deleted</h1><p class="lede">The image was removed from your library.</p></div>';
        status.textContent = 'Image deleted from your library.';
        const heading = card.querySelector('#page-title');
        window.setTimeout(() => heading?.focus(), 0);
        return;
      }
      trigger.focus();
    });

    dialog.querySelector('[data-close="cancel"]').addEventListener('click', () => {
      dialog.close('cancel');
    });

    dialog.querySelector('[data-close="delete"]').addEventListener('click', () => {
      dialog.close('delete');
    });
  </script>
</body>
</html>
