     function ImagePreviewPage() {
       const status = h('p', {
         className: 'status',
         id: 'delete-status',
         'aria-live': 'polite'
       }, '');

       const dialog = h('dialog', {
         id: 'confirm-delete',
         'aria-labelledby': 'confirm-title',
         'aria-describedby': 'confirm-copy'
       },
         h('div', { className: 'dialog-body' },
           h('div', { className: 'dialog-kicker' }, 'Delete image'),
           h('h2', { className: 'dialog-title', id: 'confirm-title' }, 'Delete this image from your library?'),
           h('p', { className: 'dialog-copy', id: 'confirm-copy' }, 'This will permanently remove the image from your library. You can\u2019t undo this action.'),
           h('div', { className: 'dialog-actions' },
             h('button', {
               type: 'button',
               className: 'secondary',
               'data-close': 'cancel',
               autofocus: true
             }, 'Cancel'),
             h('button', {
               type: 'button',
               className: 'danger',
               'data-close': 'delete'
             }, 'Delete image')
           )
         )
       );

       const page = h('section', { className: 'shell' },
         h('article', { className: 'preview-card', 'aria-labelledby': 'page-title' },
           h('div', { className: 'preview-copy' },
             h('h1', { id: 'page-title' }, 'Image preview'),
             h('p', { className: 'lede' }, 'Review your image before deleting it from the library. The confirmation dialog stays closed until you choose Delete.')
           ),
           h('div', { className: 'media' },
             h('div', { className: 'image-frame' },
               h('img', {
                 src: 'https://images.unsplash.com/photo-1516035069371-29a1b244cc32?auto=format&fit=crop&w=1600&q=80',
                 alt: 'A mountain lake reflecting a dramatic blue sky at sunset'
               })
             ),
           h('div', { className: 'actions' },
             h('p', { className: 'meta' }, 'Sunset over the alpine lake · 4.8 MB'),
             h('button', {
               type: 'button',
               className: 'trigger',
               id: 'delete-trigger',
               'aria-haspopup': 'dialog',
               'aria-controls': 'confirm-delete'
             }, 'Delete image')
           ),
           )
         ),
         status,
         dialog
       );

       return page;
     }

     const app = document.getElementById('app');
     app.appendChild(render(ImagePreviewPage()));

     const trigger = document.getElementById('delete-trigger');
     const dialog = document.getElementById('confirm-delete');
     const status = document.getElementById('delete-status');
     const card = document.querySelector('.preview-card');

     trigger.addEventListener('click', () => {
       dialog.showModal();
     });

     dialog.addEventListener('click', (event) => {
       if (event.target === dialog) {
         dialog.close('cancel');
       }
     });

     dialog.addEventListener('close', () => {
       if (dialog.returnValue === 'delete') {
         card.dataset.deleted = 'true';
         card.innerHTML = '<div class="preview-copy"><h1 id="page-title" tabindex="-1">Image deleted</h1><p class="lede">The image was removed from your library.</p></div>';
         status.textContent = 'Image deleted from your library.';
         const heading = card.querySelector('#page-title');
         window.setTimeout(() => heading?.focus(), 0);
         return;
       }
       trigger.focus();
     });
')

